import{_ as o,l,o as e,c as s,v as r,p as n,x as t,d as c,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"CDN 缓存层次与失效","description":"","frontmatter":{"title":"CDN 缓存层次与失效","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cdn-cache-hierarchy.md","filePath":"cs/cdn-cache-hierarchy.md","lastUpdated":1789023840000}'),p={name:"cs/cdn-cache-hierarchy.md"};function T(u,a,_,m,C,f){const i=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="cdn-缓存层次与失效" tabindex="-1">CDN 缓存层次与失效 <a class="header-anchor" href="#cdn-缓存层次与失效" aria-label="Permalink to &quot;CDN 缓存层次与失效&quot;">​</a></h1><div class="epigraph"><p>边缘未命中问父层，父层问源；失效用 TTL、显式 purge 或版本化 URL，否则用户看见旧表示。</p><footer>—— 据 RFC 9111 HTTP 缓存；主干 CDN 直觉课；层次缓存实践整理</footer></div><p>主干<a href="/cs/cdn-intuition">CDN 直觉</a> 已给为何近。<a href="/cs/http-semantics">HTTP 缓存头</a> 给合同。<a href="/cs/abr-streaming">上一课</a> 的分片要能命中。缺口是<strong>层次与失效</strong>：边缘–父–源、stampede、purge。本课不把边缘计算写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>每个边缘都回源会打满源 \\(C\\)。层次：L1 边缘、L2 区域、源。命中率靠 TTL 与键（含 <code>Vary</code>）。失效：短 TTL、purge API、内容哈希进 URL。惊群：TTL 同时到期，要锁定或 stale-while-revalidate。Cookie 个性化几乎不可缓存。GeoDNS 把用户钉到某边缘。</p><p>不要把 CDN 写成任意计算，那是下一课。</p><p><span class="marginnote">RFC 9111。本课不点名厂商产品名当标准。</span></p><h3 id="失效是一等公民" tabindex="-1">失效是一等公民 <a class="header-anchor" href="#失效是一等公民" aria-label="Permalink to &quot;失效是一等公民&quot;">​</a></h3><p>层次减源命中。Vary 与 Cookie 决定能否存。不可变 URL 最干净。惊群要用 stale-while-revalidate。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：用户 → 边缘 → 父 → 源。对照 DNS 缓存层次。与 EVPN 无关。</p>',11)),(e(),n(h,null,{default:t(()=>[d(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20U%5B%22%E7%94%A8%E6%88%B7%22%5D%20--%3E%20E%5B%22%E8%BE%B9%E7%BC%98%22%5D%0A%20%20E%20--%3E%20P%5B%22%E7%88%B6%E7%BC%93%E5%AD%98%22%5D%0A%20%20P%20--%3E%20O%5B%22%E6%BA%90%22%5D%0A%20%20INV%5B%22purge%2F%E7%89%88%E6%9C%AC%20URL%22%5D%20--%3E%20E%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>H3 连接在边缘终止。Origin shield 减源负载。失败：某层错误缓存 200 要 purge。RPKI 管源地址，不管缓存一致性。ABR 分片不可变则永不失效，最香。</p><p>安全：缓存投毒若键过粗。点名。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 ESI 的全部。边缘计算是下一课。后课默认：CDN 是分层 HTTP 缓存；失效是显式问题。</p><p>只靠很长 TTL 无版本化，事故时无法切。</p><p>上一课留下的缺口在本课收口；「CDN 缓存层次与失效」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/edge-compute">边缘计算</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>层次减少源命中。</li><li>键与 Vary 决定正确性。</li><li>失效靠 TTL、purge 或不可变 URL。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 9111；CDN 实践。</li></ul>',10))])}const P=o(p,[["render",T]]);export{D as __pageData,P as default};
